// The update log (updates.ts) in every language: updates 46 and 47. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES8: Readonly<Record<string, Row>> = {
  "Every tree falls, sigils with their marks, a Friend with a thousand things to say, and the Deadwood's dead": ["どの木も切り倒せる、印のついたシジル、話題が千もあるフレンド、そして Deadwood の死者たち", "모든 나무가 쓰러지고, 표식이 새겨진 인장, 할 말이 천 가지인 프렌드, 그리고 Deadwood의 망자들", "每棵树都能砍倒、带印纹的印记、有千言万语的伙伴，以及 Deadwood 的亡者", "每棵樹都能砍倒、帶印紋的印記、有千言萬語的夥伴，以及 Deadwood 的亡者", "Mọi cái cây đều đổ, ấn có dấu riêng, một Bạn có cả ngàn điều để nói, và người chết của Deadwood", "Setiap pohon tumbang, sigil dengan tandanya, Sahabat dengan seribu hal untuk dikatakan, dan orang mati Deadwood", "ต้นไม้ทุกต้นล้มได้ ผนึกพร้อมตรา เพื่อนที่มีเรื่องพูดเป็นพัน และคนตายแห่ง Deadwood", "Her ağaç devriliyor, işaretli mühürler, söyleyecek bin şeyi olan bir Dost ve Deadwood'un ölüleri", "Todos los árboles caen, sigilos con su marca, un Amigo con mil cosas que decir y los muertos del Deadwood", "Toda árvore cai, sigilos com suas marcas, um Amigo com mil coisas a dizer e os mortos do Deadwood", "Падает каждое дерево, печати со своими знаками, Друг, которому есть что сказать, и мертвецы Deadwood", "Падає кожне дерево, печатки зі своїми знаками, Друг, якому є що сказати, і мерці Deadwood"],
  "Every tree in the Realm can be cut and burnt. Palms (Woodcutting 25) on the Oasis, Southshore and Pale Isles; pines (35) on the Greyhorn, Frostpeak, Drakespine and Ironreach slopes; the dead trees of the Deadwood, Murkmire and Ashfall (55). Their logs burn for Firemaking, palm and pine logs fletch into bows (Fletching 40 and 52, Ranged 25 and 35), and a knife on deadwood logs cuts a Deadwood wand (Fletching 58): a one-handed magic weapon that autocasts like a staff, at Magic 50.": ["レルムのすべての木が伐れて燃やせるように。オアシス、サウスショア、Pale Isles のヤシ（木こり25）、グレイホーン、フロストピーク、Drakespine、アイアンリーチの斜面の松（35）、Deadwood、マークマイア、アッシュフォールの枯れ木（55）。丸太は火おこしで燃やせ、ヤシと松の丸太は弓になり（矢作り40と52、遠隔25と35）、枯れ木の丸太にナイフを使うと枯れ木のワンドができます（矢作り58）：杖のように自動詠唱する片手持ちの魔法武器で、魔法50で使えます。", "렐름의 모든 나무를 베고 태울 수 있습니다. 오아시스, 사우스쇼어, Pale Isles의 야자(벌목 25), 그레이혼, 프로스트피크, Drakespine, 아이언리치 비탈의 소나무(35), Deadwood, 머크마이어, 애시폴의 죽은 나무(55). 통나무는 불 피우기로 태우고, 야자와 소나무 통나무는 활이 되며(화살 제작 40과 52, 원거리 25와 35), 고목 통나무에 칼을 쓰면 고목 완드가 됩니다(화살 제작 58): 지팡이처럼 자동 시전하는 한손 마법 무기, 마법 50.", "王国里的每棵树都能砍伐和焚烧。绿洲、南岸和 Pale Isles 的棕榈（伐木 25）；灰角、霜峰、Drakespine 和铁境山坡的松树（35）；Deadwood、暗沼和灰落的枯树（55）。它们的原木可用于生火，棕榈和松木可以做成弓（制箭 40 和 52，远程 25 和 35），用小刀加工枯木原木可制成枯木魔杖（制箭 58）：一种像法杖一样自动施法的单手魔法武器，需魔法 50。", "王國裡的每棵樹都能砍伐和焚燒。綠洲、南岸和 Pale Isles 的棕櫚（伐木 25）；灰角、霜峰、Drakespine 和鐵境山坡的松樹（35）；Deadwood、暗沼和灰落的枯樹（55）。它們的原木可用於生火，棕櫚和松木可以做成弓（制箭 40 和 52，遠端 25 和 35），用小刀加工枯木原木可製成枯木魔杖（制箭 58）：一種像法杖一樣自動施法的單手魔法武器，需魔法 50。", "Mọi cái cây trong Vương quốc đều chặt và đốt được. Cọ (Đốn củi 25) ở Ốc đảo, Southshore và Pale Isles; thông (35) trên sườn Greyhorn, Frostpeak, Drakespine và Ironreach; cây chết ở Deadwood, Murkmire và Ashfall (55). Gỗ của chúng đốt được cho Nhóm lửa, gỗ cọ và thông làm được cung (Làm tên 40 và 52, Tầm xa 25 và 35), và dùng dao lên gỗ cây chết để gọt Đũa gỗ chết (Làm tên 58): vũ khí phép một tay tự thi triển như gậy phép, ở Phép thuật 50.", "Setiap pohon di Realm bisa ditebang dan dibakar. Palem (Menebang 25) di Oasis, Southshore, dan Pale Isles; pinus (35) di lereng Greyhorn, Frostpeak, Drakespine, dan Ironreach; pohon mati di Deadwood, Murkmire, dan Ashfall (55). Kayunya terbakar untuk Membuat api, kayu palem dan pinus jadi busur (Membuat panah 40 dan 52, Jarak jauh 25 dan 35), dan pisau pada kayu mati mengukir Tongkat sihir kayu mati (Membuat panah 58): senjata sihir satu tangan yang merapal otomatis seperti tongkat, di Sihir 50.", "ต้นไม้ทุกต้นในอาณาจักรตัดและเผาได้ ปาล์ม (ตัดไม้ 25) ที่โอเอซิส เซาท์ชอร์ และ Pale Isles สน (35) บนลาดเกรย์ฮอร์น ฟรอสต์พีก Drakespine และไอรอนรีช ต้นไม้ตายใน Deadwood เมิร์กไมร์ และแอชฟอลล์ (55) ท่อนไม้เผาเพื่อก่อไฟได้ ไม้ปาล์มและสนทำเป็นธนูได้ (ทำลูกธนู 40 และ 52 ระยะไกล 25 และ 35) และใช้มีดกับไม้ตายได้ไม้กายสิทธิ์ไม้ตาย (ทำลูกธนู 58): อาวุธเวทมือเดียวที่ร่ายอัตโนมัติเหมือนคทา ที่เวทมนตร์ 50", "Diyar'daki her ağaç kesilip yakılabiliyor. Vaha, Southshore ve Pale Isles'ta palmiyeler (Odunculuk 25); Greyhorn, Frostpeak, Drakespine ve Ironreach yamaçlarında çamlar (35); Deadwood, Murkmire ve Ashfall'un kuru ağaçları (55). Kütükleri Ateş yakmada yanar, palmiye ve çam kütükleri yay olur (Okçuluk zanaatı 40 ve 52, Menzilli 25 ve 35) ve kuru ağaç kütüğüne bıçak bir Kuru ağaç değnek oyar (Okçuluk zanaatı 58): asa gibi otomatik büyü yapan tek elli bir büyü silahı, Büyü 50'de.", "Todos los árboles del Reino se pueden talar y quemar. Palmeras (Tala 25) en el Oasis, Southshore y las Pale Isles; pinos (35) en las laderas del Greyhorn, Frostpeak, Drakespine e Ironreach; los árboles muertos del Deadwood, el Murkmire y Ashfall (55). Sus troncos arden en Hogueras, los de palmera y pino se hacen arcos (Flechería 40 y 52, A distancia 25 y 35), y un cuchillo sobre troncos de leña muerta talla una Varita de leña muerta (Flechería 58): un arma mágica de una mano que lanza sola como un bastón, con Magia 50.", "Toda árvore do Reino pode ser cortada e queimada. Palmeiras (Lenhador 25) no Oásis, em Southshore e nas Pale Isles; pinheiros (35) nas encostas do Greyhorn, Frostpeak, Drakespine e Ironreach; as árvores mortas do Deadwood, do Murkmire e de Ashfall (55). As toras queimam na Fogueira, toras de palmeira e pinheiro viram arcos (Arquearia 40 e 52, À distância 25 e 35), e uma faca em toras de madeira morta entalha uma Varinha de madeira morta (Arquearia 58): uma arma mágica de uma mão que lança sozinha como um cajado, com Magia 50.", "Любое дерево Королевства можно срубить и сжечь. Пальмы (Рубка леса 25) в Оазисе, Саутшоре и на Pale Isles; сосны (35) на склонах Грейхорна, Фростпика, Drakespine и Айронрича; мёртвые деревья Deadwood, Мёркмайра и Эшфолла (55). Их брёвна горят для Разжигания огня, из пальмовых и сосновых делают луки (Изготовление стрел 40 и 52, Стрельба 25 и 35), а нож по мёртвому дереву вырезает Жезл из мёртвого дерева (Изготовление стрел 58): одноручное магическое оружие, которое само творит заклинания, как посох, на Магии 50.", "Будь-яке дерево Королівства можна зрубати й спалити. Пальми (Рубання дерев 25) в Оазисі, Саутшорі та на Pale Isles; сосни (35) на схилах Грейгорна, Фростпіку, Drakespine й Айронріча; мертві дерева Deadwood, Мьоркмайра й Ешфолла (55). Їхні колоди горять для Розпалювання вогню, з пальмових і соснових роблять луки (Виготовлення стріл 40 і 52, Стрільба 25 і 35), а ніж по мертвому дереву вирізає Жезл з мертвого дерева (Виготовлення стріл 58): одноручну магічну зброю, що сама творить заклинання, як посох, на Магії 50."],
  "Every sigil carries its own mark on the stone: a swirl for breeze, a wave for tide, a flame for ember, an eye for thought, a bolt for storm, a path's arrow, a flower for bloom, a star, a crescent for shade, a dark ring for hollow.": ["どのシジルにも石に独自の印が：そよ風には渦、潮には波、残り火には炎、思念には目、嵐には稲妻、道には矢印、開花には花、星、影には三日月、虚ろには黒い輪。", "모든 인장의 돌에 고유한 표식이 있습니다: 미풍은 소용돌이, 조수는 물결, 불씨는 불꽃, 사념은 눈, 폭풍은 번개, 길은 화살표, 개화는 꽃, 별, 그림자는 초승달, 공허는 검은 고리.", "每种印记的石头上都有自己的纹样：微风是漩涡，潮汐是波浪，余烬是火焰，思绪是眼睛，风暴是闪电，道路是箭头，绽放是花朵，星辰是星星，阴影是新月，虚空是黑环。", "每種印記的石頭上都有自己的紋樣：微風是漩渦，潮汐是波浪，餘燼是火焰，思緒是眼睛，風暴是閃電，道路是箭頭，綻放是花朵，星辰是星星，陰影是新月，虛空是黑環。", "Mỗi ấn mang dấu riêng trên đá: xoáy cho gió nhẹ, sóng cho thủy triều, ngọn lửa cho than hồng, con mắt cho tư tưởng, tia sét cho bão, mũi tên cho con đường, bông hoa cho nở rộ, ngôi sao, trăng lưỡi liềm cho bóng tối, vòng đen cho hư không.", "Setiap sigil membawa tandanya sendiri di batu: pusaran untuk angin sepoi, ombak untuk pasang, nyala untuk bara, mata untuk pikiran, petir untuk badai, panah untuk jalan, bunga untuk mekar, bintang, bulan sabit untuk bayang, cincin gelap untuk hampa.", "ผนึกทุกชนิดมีตราของตัวเองบนหิน: วงก้นหอยสำหรับสายลม คลื่นสำหรับกระแสน้ำ เปลวไฟสำหรับถ่านไฟ ดวงตาสำหรับความคิด สายฟ้าสำหรับพายุ ลูกศรสำหรับเส้นทาง ดอกไม้สำหรับการเบ่งบาน ดาว จันทร์เสี้ยวสำหรับเงา และวงแหวนดำสำหรับความว่างเปล่า", "Her mühür taşın üstünde kendi işaretini taşıyor: esinti için girdap, gelgit için dalga, kor için alev, düşünce için göz, fırtına için şimşek, yol için ok, çiçeklenme için çiçek, yıldız, gölge için hilal, boşluk için kara bir halka.", "Cada sigilo lleva su marca en la piedra: un remolino para la brisa, una ola para la marea, una llama para la brasa, un ojo para el pensamiento, un rayo para la tormenta, la flecha del camino, una flor para la floración, una estrella, una media luna para la sombra y un anillo oscuro para el hueco.", "Cada sigilo traz sua marca na pedra: um redemoinho para a brisa, uma onda para a maré, uma chama para a brasa, um olho para o pensamento, um raio para a tempestade, a seta do caminho, uma flor para o florescer, uma estrela, uma lua crescente para a sombra e um anel escuro para o oco.", "На камне каждой печати свой знак: завиток для бриза, волна для прилива, пламя для тлеющего угля, глаз для мысли, молния для бури, стрелка для пути, цветок для цветения, звезда, полумесяц для тени и тёмное кольцо для пустоты.", "На камені кожної печатки свій знак: завиток для бризу, хвиля для припливу, полум'я для жарини, око для думки, блискавка для бурі, стрілка для шляху, квітка для цвітіння, зірка, півмісяць для тіні й темне кільце для порожнечі."],
  "The Deadwood is full of its dead: fourteen roofless ruined houses with what the people left behind (beds rotted to lace, a table laid for four), Ashworth Hall with its tomb under the floor, six named crypts with stories carved on the tombs inside (the Three Sisters, the Namekeeper's, one with the lid moved from the inside), railed family plots, tombs and obelisks, bone-heaps, and three kinds of headstone with epitaphs worth reading.": ["Deadwood は死者でいっぱいです：人々が残していったもの（朽ちてレースのようになったベッド、4人分の支度がされた食卓）が残る屋根のない廃屋が14軒、床下に墓のある Ashworth Hall、中の墓に物語が刻まれた名のある地下墓所が6つ（三姉妹の墓、名守りの墓、内側から蓋が動かされた墓）、柵で囲まれた家族の墓所、墓と方尖塔、骨の山、そして読む価値のある墓碑銘が刻まれた3種類の墓石。", "Deadwood는 망자들로 가득합니다: 사람들이 남기고 간 것(삭아서 레이스가 된 침대, 네 사람분 차려진 식탁)이 있는 지붕 없는 폐가 열넷, 바닥 밑에 무덤이 있는 Ashworth Hall, 안의 무덤에 이야기가 새겨진 이름 붙은 지하묘지 여섯(세 자매의 묘, 이름지기의 묘, 안에서 뚜껑이 밀린 묘 하나), 난간 두른 가족 묘역, 무덤과 오벨리스크, 뼈 더미, 그리고 읽어 볼 만한 묘비명이 새겨진 세 종류의 묘비.", "Deadwood 满是亡者：十四座无顶的废屋，留着人们遗下的东西（烂成蕾丝般的床、摆好四人份的餐桌），地板下有墓的 Ashworth Hall，六座有名字的地穴，里面的墓上刻着故事（三姐妹墓、名字守护者之墓、一座盖子从里面被推开的墓），围着栏杆的家族墓地，墓碑和方尖碑，骨堆，以及三种刻着值得一读的墓志铭的墓碑。", "Deadwood 滿是亡者：十四座無頂的廢屋，留著人們遺下的東西（爛成蕾絲般的床、擺好四人份的餐桌），地板下有墓的 Ashworth Hall，六座有名字的地穴，裡面的墓上刻著故事（三姐妹墓、名字守護者之墓、一座蓋子從裡面被推開的墓），圍著欄杆的家族墓地，墓碑和方尖碑，骨堆，以及三種刻著值得一讀的墓誌銘的墓碑。", "Deadwood đầy người chết: mười bốn ngôi nhà đổ nát không mái với những gì người ta để lại (giường mục thành ren, bàn bày sẵn cho bốn người), Ashworth Hall với ngôi mộ dưới sàn, sáu hầm mộ có tên với câu chuyện khắc trên các ngôi mộ bên trong (Ba Chị Em, mộ của Người Giữ Tên, một ngôi mộ có nắp bị đẩy từ bên trong), các khu mộ gia đình có rào, lăng mộ và cột tháp, đống xương, và ba loại bia mộ với văn bia đáng đọc.", "Deadwood penuh orang mati: empat belas rumah reruntuhan tanpa atap dengan apa yang ditinggalkan penghuninya (ranjang yang lapuk menjadi renda, meja yang ditata untuk empat orang), Ashworth Hall dengan makam di bawah lantainya, enam kripta bernama dengan kisah terpahat di makam di dalamnya (Tiga Saudari, milik Penjaga Nama, satu dengan tutup yang digeser dari dalam), petak makam keluarga berpagar, makam dan obelisk, tumpukan tulang, dan tiga jenis nisan dengan epitaf yang layak dibaca.", "Deadwood เต็มไปด้วยคนตาย: บ้านร้างไร้หลังคาสิบสี่หลังพร้อมสิ่งที่ผู้คนทิ้งไว้ (เตียงผุจนเหมือนลูกไม้ โต๊ะที่จัดไว้สำหรับสี่คน) Ashworth Hall ที่มีหลุมศพใต้พื้น สุสานใต้ดินมีชื่อหกแห่งที่มีเรื่องราวสลักบนหลุมศพข้างใน (สามพี่น้อง ของผู้รักษานาม และหลุมหนึ่งที่ฝาถูกเลื่อนจากข้างใน) แปลงสุสานครอบครัวมีรั้ว หลุมศพและเสาโอเบลิสก์ กองกระดูก และป้ายหลุมศพสามแบบพร้อมคำจารึกที่น่าอ่าน", "Deadwood ölüleriyle dolu: insanların geride bıraktıklarıyla (dantel gibi çürümüş yataklar, dört kişilik kurulmuş bir masa) on dört çatısız yıkık ev, zemininin altında mezarı olan Ashworth Hall, içindeki mezarlara hikâyeler kazınmış altı adlı mahzen (Üç Kız Kardeş, İsim Bekçisi'ninki, kapağı içeriden oynatılmış biri), parmaklıklı aile mezarlıkları, mezarlar ve dikilitaşlar, kemik yığınları ve okumaya değer kitabeleri olan üç tür mezar taşı.", "El Deadwood está lleno de sus muertos: catorce casas en ruinas sin tejado con lo que dejó su gente (camas podridas hasta parecer encaje, una mesa puesta para cuatro), Ashworth Hall con su tumba bajo el suelo, seis criptas con nombre y historias talladas en sus tumbas (las Tres Hermanas, la del Guardanombres, una con la losa movida desde dentro), parcelas familiares con verja, tumbas y obeliscos, montones de huesos y tres clases de lápida con epitafios que vale la pena leer.", "O Deadwood está cheio dos seus mortos: catorze casas em ruínas sem telhado com o que o povo deixou para trás (camas apodrecidas até virar renda, uma mesa posta para quatro), Ashworth Hall com seu túmulo sob o piso, seis criptas com nome e histórias entalhadas nos túmulos lá dentro (as Três Irmãs, a do Guarda-Nomes, uma com a tampa movida por dentro), jazigos de família com grade, túmulos e obeliscos, pilhas de ossos e três tipos de lápide com epitáfios que valem a leitura.", "Deadwood полон своих мертвецов: четырнадцать разрушенных домов без крыш с тем, что оставили люди (кровати, истлевшие до кружева, стол, накрытый на четверых), Ashworth Hall с гробницей под полом, шесть именных склепов с историями, высеченными на гробницах внутри (Три сестры, склеп Хранителя имён, один с крышкой, сдвинутой изнутри), огороженные семейные участки, гробницы и обелиски, груды костей и три вида надгробий с эпитафиями, которые стоит прочесть.", "Deadwood повний своїх мерців: чотирнадцять зруйнованих будинків без дахів із тим, що залишили люди (ліжка, зотлілі до мережива, стіл, накритий на чотирьох), Ashworth Hall із гробницею під підлогою, шість іменних склепів з історіями, висіченими на гробницях усередині (Три сестри, склеп Хранителя імен, один із накривкою, зсунутою зсередини), огороджені родинні ділянки, гробниці й обеліски, купи кісток і три види надгробків з епітафіями, які варто прочитати."],
  "Your Friend has a far bigger bank of things to say: every family has its own remarks for every skill you train (fishing, mining, cooking, thieving, offering bones), storms, fog, snow and lava underfoot, villages, ruins, a full pack, a shop, a bank, a level, your pet, and idle chatter drawn at random so no two Friends sound alike. Overhead text now sits above your name and tag instead of behind them.": ["フレンドの話のネタがぐっと増えました：どのファミリーにも、鍛えているスキル（釣り、採掘、料理、盗み、骨の奉納）、嵐、霧、足元の雪や溶岩、村、廃墟、いっぱいの荷物、店、銀行、レベルアップ、ペットについての独自の一言があり、ランダムな雑談もあるので、同じように話すフレンドは二人といません。頭上のテキストは名前とタグの後ろではなく上に表示されるようになりました。", "프렌드의 할 말 창고가 훨씬 커졌습니다: 가문마다 훈련하는 스킬(낚시, 채광, 요리, 도둑질, 뼈 바치기), 폭풍, 안개, 발밑의 눈과 용암, 마을, 폐허, 가득 찬 가방, 상점, 은행, 레벨 업, 펫에 대한 고유한 한마디가 있고, 무작위 잡담도 있어 똑같이 말하는 프렌드는 없습니다. 머리 위 글자는 이제 이름과 태그 뒤가 아니라 위에 뜹니다.", "伙伴要说的话大大增加了：每个家族对你训练的每项技能（钓鱼、采矿、烹饪、偷窃、供奉骨头）、风暴、雾、脚下的雪和岩浆、村庄、废墟、满背包、商店、银行、升级、你的宠物都有自己的评论，还有随机抽取的闲聊，所以没有两个伙伴说话一样。头顶文字现在显示在你的名字和标签上方，而不是后面。", "夥伴要說的話大大增加了：每個家族對你訓練的每項技能（釣魚、採礦、烹飪、偷竊、供奉骨頭）、風暴、霧、腳下的雪和岩漿、村莊、廢墟、滿背包、商店、銀行、升級、你的寵物都有自己的評論，還有隨機抽取的閒聊，所以沒有兩個夥伴說話一樣。頭頂文字現在顯示在你的名字和標籤上方，而不是後面。", "Bạn của bạn có kho chuyện để nói lớn hơn nhiều: mỗi gia tộc có lời nhận xét riêng cho mọi kỹ năng bạn luyện (câu cá, khai mỏ, nấu ăn, trộm cắp, dâng xương), bão, sương mù, tuyết và dung nham dưới chân, làng mạc, phế tích, túi đầy, cửa hàng, ngân hàng, lên cấp, thú cưng của bạn, và chuyện phiếm ngẫu nhiên nên không có hai Bạn nào nói giống nhau. Chữ trên đầu giờ nằm trên tên và thẻ của bạn thay vì phía sau.", "Sahabatmu punya bank kata-kata yang jauh lebih besar: setiap keluarga punya komentarnya sendiri untuk setiap keahlian yang kau latih (memancing, menambang, memasak, mencuri, mempersembahkan tulang), badai, kabut, salju dan lava di bawah kaki, desa, reruntuhan, tas penuh, toko, bank, naik level, peliharaanmu, dan obrolan iseng yang diambil acak sehingga tak ada dua Sahabat yang bicara sama. Teks di atas kepala kini di atas nama dan tagmu, bukan di belakangnya.", "เพื่อนของคุณมีคลังคำพูดใหญ่ขึ้นมาก: ทุกตระกูลมีคำพูดของตัวเองสำหรับทุกทักษะที่คุณฝึก (ตกปลา ขุดแร่ ทำอาหาร ขโมย ถวายกระดูก) พายุ หมอก หิมะและลาวาใต้เท้า หมู่บ้าน ซากปรักหักพัง กระเป๋าเต็ม ร้านค้า ธนาคาร เลเวลอัป สัตว์เลี้ยงของคุณ และคุยเล่นที่สุ่มมา ไม่มีเพื่อนสองตัวที่พูดเหมือนกัน ข้อความเหนือหัวตอนนี้อยู่เหนือชื่อและแท็กแทนที่จะอยู่ข้างหลัง", "Dostunun söyleyecekleri çok daha büyük bir depo: her ailenin eğittiğin her beceri (balıkçılık, madencilik, aşçılık, hırsızlık, kemik sunma), fırtınalar, sis, ayağının altındaki kar ve lav, köyler, harabeler, dolu bir çanta, bir dükkân, bir banka, bir seviye, evcil hayvanın için kendi sözleri ve rastgele seçilen boş muhabbetleri var; böylece iki Dost aynı konuşmuyor. Baş üstü yazılar artık adının ve etiketinin arkasında değil üstünde.", "Tu Amigo tiene un repertorio mucho mayor: cada familia tiene sus propios comentarios para cada habilidad que entrenas (pesca, minería, cocina, robo, ofrecer huesos), tormentas, niebla, nieve y lava bajo los pies, pueblos, ruinas, la mochila llena, una tienda, un banco, un nivel, tu mascota y charla ociosa al azar, así que no hay dos Amigos que suenen igual. El texto sobre la cabeza aparece ahora encima de tu nombre y etiqueta, no detrás.", "Seu Amigo tem um repertório bem maior: cada família tem seus comentários para cada habilidade que você treina (pesca, mineração, culinária, roubo, oferecer ossos), tempestades, neblina, neve e lava sob os pés, vilas, ruínas, mochila cheia, uma loja, um banco, um nível, seu bichinho e conversa à toa sorteada, então não há dois Amigos que falem igual. O texto sobre a cabeça agora fica acima do seu nome e tag, não atrás.", "У вашего Друга гораздо больше слов: у каждой семьи свои реплики на каждый навык, который вы качаете (рыбалка, добыча, готовка, воровство, подношение костей), на грозы, туман, снег и лаву под ногами, деревни, руины, полную сумку, лавку, банк, новый уровень, вашего питомца, и случайная болтовня, так что двух одинаковых Друзей не бывает. Текст над головой теперь над вашим именем и меткой, а не за ними.", "У вашого Друга набагато більше слів: у кожної родини свої репліки на кожну навичку, яку ви розвиваєте (риболовля, видобуток, готування, крадіжка, підношення кісток), на грози, туман, сніг і лаву під ногами, села, руїни, повну сумку, крамницю, банк, новий рівень, вашого улюбленця, і випадкова балачка, тож двох однакових Друзів не буває. Текст над головою тепер над вашим ім'ям і міткою, а не за ними."],
  "Presence takes longer: it is meant to be the slowest skill in the Realm, so all stray Presence XP is halved. The profile shows its progress bar. The Presence icon is an adventurer (hat, cape and staff) rather than a second Faith.": ["名声の上がり方がゆっくりに：レルムで最も遅いスキルにするため、細かな名声経験値はすべて半分になりました。プロフィールに進捗バーが表示されます。名声のアイコンは信仰と重複しない冒険者（帽子、マント、杖）になりました。", "명성이 더 오래 걸립니다: 렐름에서 가장 느린 스킬이 되도록, 자잘한 명성 경험치는 모두 절반이 되었습니다. 프로필에 진행 막대가 보입니다. 명성 아이콘은 두 번째 신앙이 아니라 모험가(모자, 망토, 지팡이)입니다.", "声望涨得更慢了：它本就该是王国里最慢的技能，所以零散的声望经验全部减半。档案中会显示进度条。声望图标换成了一位冒险者（帽子、披风和法杖），不再像第二个信仰图标。", "聲望漲得更慢了：它本就該是王國裡最慢的技能，所以零散的聲望經驗全部減半。檔案中會顯示進度條。聲望圖示換成了一位冒險者（帽子、披風和法杖），不再像第二個信仰圖示。", "Danh tiếng lâu hơn: nó được thiết kế là kỹ năng chậm nhất Vương quốc, nên mọi XP Danh tiếng lẻ đều giảm một nửa. Hồ sơ hiện thanh tiến độ. Biểu tượng Danh tiếng là một nhà thám hiểm (mũ, áo choàng và gậy) thay vì một Đức tin thứ hai.", "Kehadiran makan waktu lebih lama: ia memang dimaksudkan sebagai keahlian paling lambat di Realm, jadi semua XP Kehadiran kecil dibagi dua. Profil menampilkan bar kemajuannya. Ikon Kehadiran adalah seorang petualang (topi, jubah, dan tongkat), bukan Iman kedua.", "ชื่อเสียงใช้เวลานานขึ้น: ตั้งใจให้เป็นทักษะที่ช้าที่สุดในอาณาจักร XP ชื่อเสียงเล็กๆ น้อยๆ ทั้งหมดจึงลดลงครึ่งหนึ่ง โปรไฟล์แสดงแถบความคืบหน้า ไอคอนชื่อเสียงเป็นนักผจญภัย (หมวก ผ้าคลุม และคทา) แทนที่จะเป็นศรัทธาอันที่สอง", "Şöhret daha uzun sürüyor: Diyar'ın en yavaş becerisi olsun diye tüm başıboş Şöhret XP'si yarıya indirildi. Profil ilerleme çubuğunu gösteriyor. Şöhret simgesi ikinci bir İnanç yerine bir maceracı (şapka, pelerin ve asa).", "La Presencia tarda más: está pensada para ser la habilidad más lenta del Reino, así que toda la XP de Presencia suelta se reduce a la mitad. El perfil muestra su barra de progreso. El icono de Presencia es un aventurero (sombrero, capa y bastón) en lugar de una segunda Fe.", "A Presença demora mais: ela foi feita para ser a habilidade mais lenta do Reino, então todo XP de Presença avulso caiu pela metade. O perfil mostra a barra de progresso. O ícone de Presença é um aventureiro (chapéu, capa e cajado) em vez de uma segunda Fé.", "Слава растёт дольше: задумано, что это самый медленный навык Королевства, поэтому весь случайный опыт Славы уменьшен вдвое. В профиле видна полоска прогресса. Значок Славы — искатель приключений (шляпа, плащ и посох), а не вторая Вера.", "Слава росте довше: задумано, що це найповільніша навичка Королівства, тож увесь випадковий досвід Слави зменшено вдвічі. У профілі видно смужку прогресу. Значок Слави — шукач пригод (капелюх, плащ і посох), а не друга Віра."],
  "The spellbook's tabs are the same dark brown as the graphics buttons; examining a spell lists the sigils and any quest it needs in the chat; the chat can be folded away with the arrow in its corner. Settings has a Nameplates choice (Full, Name only, Hidden) for what shows over players, and the save and restore buttons wear the same dark style.": ["呪文書のタブはグラフィックボタンと同じこげ茶色に。呪文を調べると必要なシジルとクエストがチャットに表示されます。チャットは角の矢印でたためます。設定にネームプレートの選択（フル、名前のみ、非表示）が加わり、プレイヤーの上に表示する内容を選べます。保存と復元のボタンも同じ暗いスタイルに。", "주문서 탭이 그래픽 버튼과 같은 짙은 갈색이 되었고, 주문을 살펴보면 필요한 인장과 퀘스트가 채팅에 나옵니다. 채팅은 모서리 화살표로 접을 수 있습니다. 설정에 이름표 선택(전체, 이름만, 숨김)이 생겨 플레이어 위에 무엇을 보일지 고를 수 있고, 저장과 복원 버튼도 같은 어두운 스타일입니다.", "法术书的标签和图形按钮一样是深棕色；查看法术会在聊天中列出所需的印记和任务；聊天框可以用角落的箭头收起。设置中新增名牌选项（完整、仅名字、隐藏），决定玩家头上显示什么，保存和恢复按钮也换成同样的深色风格。", "法術書的分頁和圖形按鈕一樣是深棕色；查看法術會在聊天中列出所需的印記和任務；聊天框可以用角落的箭頭收起。設定中新增名牌選項（完整、僅名字、隱藏），決定玩家頭上顯示什麼，保存和恢復按鈕也換成同樣的深色風格。", "Các thẻ của sách phép có cùng màu nâu sẫm như nút đồ họa; xem xét một phép sẽ liệt kê ấn và nhiệm vụ cần thiết trong khung trò chuyện; khung trò chuyện có thể gập lại bằng mũi tên ở góc. Cài đặt có lựa chọn Bảng tên (Đầy đủ, Chỉ tên, Ẩn) cho thứ hiện trên đầu người chơi, và nút lưu và khôi phục có cùng phong cách tối.", "Tab buku mantra kini cokelat tua yang sama dengan tombol grafis; memeriksa mantra mencantumkan sigil dan misi yang dibutuhkan di obrolan; obrolan bisa dilipat dengan panah di sudutnya. Pengaturan punya pilihan Papan nama (Lengkap, Nama saja, Tersembunyi) untuk apa yang tampil di atas pemain, dan tombol simpan dan pulihkan memakai gaya gelap yang sama.", "แท็บของคัมภีร์เวทเป็นสีน้ำตาลเข้มเหมือนปุ่มกราฟิก การตรวจดูคาถาจะแสดงผนึกและเควสต์ที่ต้องใช้ในแชท แชทพับเก็บได้ด้วยลูกศรที่มุม การตั้งค่ามีตัวเลือกป้ายชื่อ (เต็ม ชื่ออย่างเดียว ซ่อน) สำหรับสิ่งที่แสดงเหนือผู้เล่น และปุ่มบันทึกกับกู้คืนใช้สไตล์มืดแบบเดียวกัน", "Büyü kitabının sekmeleri grafik düğmeleriyle aynı koyu kahverengi; bir büyüyü incelemek gerekli mühürleri ve görevi sohbette listeliyor; sohbet köşesindeki okla katlanabiliyor. Ayarlar'da oyuncuların üstünde ne görüneceği için bir İsim levhası seçimi (Tam, Yalnızca ad, Gizli) var ve kaydet ile geri yükle düğmeleri aynı koyu tarzda.", "Las pestañas del libro de hechizos son del mismo marrón oscuro que los botones de gráficos; examinar un hechizo muestra en el chat los sigilos y la misión que pide; el chat se puede plegar con la flecha de su esquina. Los ajustes tienen una opción de Placas de nombre (Completa, Solo nombre, Oculta) para lo que se ve sobre los jugadores, y los botones de guardar y restaurar llevan el mismo estilo oscuro.", "As abas do livro de feitiços têm o mesmo marrom escuro dos botões de gráficos; examinar um feitiço lista no chat os sigilos e a missão que ele pede; o chat pode ser recolhido pela seta no canto. As configurações têm uma opção de Placas de nome (Completa, Só o nome, Oculta) para o que aparece sobre os jogadores, e os botões de salvar e restaurar usam o mesmo estilo escuro.", "Вкладки книги заклинаний того же тёмно-коричневого цвета, что и кнопки графики; осмотр заклинания выводит в чат нужные печати и квест; чат можно свернуть стрелкой в углу. В настройках появился выбор табличек с именами (Полностью, Только имя, Скрыто) для того, что видно над игроками, а кнопки сохранения и восстановления оформлены в том же тёмном стиле.", "Вкладки книги заклинань того самого темно-коричневого кольору, що й кнопки графіки; огляд заклинання виводить у чат потрібні печатки й квест; чат можна згорнути стрілкою в куті. У налаштуваннях з'явився вибір табличок з іменами (Повністю, Лише ім'я, Приховано) для того, що видно над гравцями, а кнопки збереження й відновлення оформлено в тому ж темному стилі."],
  "A Friend that talks back, rumours in every village, and the Realm's history": ["話しかけてくるフレンド、どの村にもある噂、そしてレルムの歴史", "말대꾸하는 프렌드, 마을마다 도는 소문, 그리고 렐름의 역사", "会回嘴的伙伴、每个村子的传闻，以及王国的历史", "會回嘴的夥伴、每個村子的傳聞，以及王國的歷史", "Một Bạn biết đáp lời, tin đồn ở mọi làng, và lịch sử Vương quốc", "Sahabat yang membalas bicara, kabar burung di setiap desa, dan sejarah Realm", "เพื่อนที่พูดโต้ตอบ ข่าวลือในทุกหมู่บ้าน และประวัติศาสตร์ของอาณาจักร", "Karşılık veren bir Dost, her köyde söylentiler ve Diyar'ın tarihi", "Un Amigo que contesta, rumores en cada pueblo y la historia del Reino", "Um Amigo que responde, boatos em cada vila e a história do Reino", "Друг, который отвечает, слухи в каждой деревне и история Королевства", "Друг, що відповідає, чутки в кожному селі й історія Королівства"],
  "Your Friend has a voice. Now and then it remarks on the world in its family's own manner: a Skeleton is dry (\"Finally. Someone who planned ahead.\" at a grave), a Colossus blunt (\"Big.\"), a Hoverer wants to know what's over the hill, a Hollow Friend hears things hum. It speaks to where you are, the weather, the hour, what's near, what you're doing, and what you've lived: first dragons, first deaths, old haunts. The line shows over its head and in chat as your name; on Full, players nearby hear it. Settings: Friend speech, Full, Reduced, Rare or Off.": ["フレンドに声ができました。ときどき、ファミリーらしい口調で世界について一言：スケルトンは皮肉っぽく（墓の前で「やっと先のことを考えた奴がいた。」）、コロッサスはぶっきらぼう（「でかい。」）、ホバラーは丘の向こうが気になり、ホロウのフレンドは何かが唸るのを聞きます。今いる場所、天気、時刻、近くにあるもの、していること、そしてこれまでの経験（最初のドラゴン、最初の死、なじみの場所）について話します。セリフは頭上とチャットにあなたの名前で表示され、「フル」なら近くのプレイヤーにも聞こえます。設定：フレンドの会話、フル、控えめ、まれ、オフ。", "프렌드에게 목소리가 생겼습니다. 가끔 가문 고유의 말투로 세상에 한마디 합니다: 스켈레톤은 무덤덤하게(무덤 앞에서 \"드디어. 미리 준비한 사람이 있군.\"), 콜로서스는 퉁명스럽게(\"크다.\"), 호버러는 언덕 너머가 궁금하고, 할로우 프렌드는 무언가 웅웅대는 걸 듣습니다. 지금 있는 곳, 날씨, 시간, 근처의 것, 하는 일, 그리고 겪어 온 것(첫 드래곤, 첫 죽음, 옛 단골 장소)에 대해 말합니다. 대사는 머리 위와 채팅에 당신 이름으로 나오고, '전체'에선 근처 플레이어도 듣습니다. 설정: 프렌드 대화, 전체, 줄임, 드물게, 끄기.", "你的伙伴有了声音。它时不时会以家族特有的方式评论世界：骷髅冷幽默（在坟前说「终于。总算有人提前做了打算。」），巨像直来直去（「大。」），悬浮者想知道山那边有什么，虚空伙伴会听见东西在嗡鸣。它会谈论你所在的地方、天气、时辰、附近有什么、你在做什么，以及你经历过的事：第一条龙、第一次死亡、常去的老地方。台词会显示在它头顶，并以你的名字出现在聊天中；在「完整」模式下附近的玩家也能听到。设置：伙伴说话，完整、减少、稀少或关闭。", "你的夥伴有了聲音。牠時不時會以家族特有的方式評論世界：骷髏冷幽默（在墳前說「終於。總算有人提前做了打算。」），巨像直來直往（「大。」），懸浮者想知道山那邊有什麼，虛空夥伴會聽見東西在嗡鳴。牠會談論你所在的地方、天氣、時辰、附近有什麼、你在做什麼，以及你經歷過的事：第一條龍、第一次死亡、常去的老地方。台詞會顯示在牠頭頂，並以你的名字出現在聊天中；在「完整」模式下附近的玩家也能聽到。設定：夥伴說話，完整、減少、稀少或關閉。", "Bạn của bạn có giọng nói. Thỉnh thoảng nó nhận xét về thế giới theo cách riêng của gia tộc: Skeleton khô khan (\"Cuối cùng. Có người tính trước.\" ở một ngôi mộ), Colossus cộc lốc (\"To.\"), Hoverer muốn biết bên kia đồi có gì, Bạn Hollow nghe thấy thứ gì ngân lên. Nó nói về nơi bạn đang ở, thời tiết, giờ giấc, thứ ở gần, việc bạn đang làm, và những gì bạn đã trải qua: những con rồng đầu tiên, những lần chết đầu tiên, chốn quen cũ. Câu nói hiện trên đầu nó và trong khung trò chuyện dưới tên bạn; ở chế độ Đầy đủ, người chơi gần đó nghe được. Cài đặt: Lời Bạn nói, Đầy đủ, Giảm, Hiếm hoặc Tắt.", "Sahabatmu punya suara. Sesekali ia berkomentar tentang dunia dengan gaya keluarganya: Skeleton datar (\"Akhirnya. Ada yang merencanakan.\" di kuburan), Colossus blak-blakan (\"Besar.\"), Hoverer ingin tahu ada apa di balik bukit, Sahabat Hollow mendengar sesuatu berdengung. Ia bicara tentang tempatmu berada, cuaca, waktu, yang ada di dekat, yang sedang kau lakukan, dan yang pernah kau alami: naga pertama, kematian pertama, tempat lama. Ucapannya tampil di atas kepalanya dan di obrolan atas namamu; di mode Lengkap, pemain di dekatmu mendengarnya. Pengaturan: Bicara Sahabat, Lengkap, Dikurangi, Jarang, atau Mati.", "เพื่อนของคุณมีเสียงแล้ว บางครั้งมันจะพูดถึงโลกในแบบเฉพาะของตระกูล: Skeleton พูดแห้งๆ (\"ในที่สุด มีคนวางแผนล่วงหน้าสักที\" ที่หลุมศพ) Colossus พูดห้วนๆ (\"ใหญ่\") Hoverer อยากรู้ว่าหลังเนินมีอะไร เพื่อน Hollow ได้ยินบางอย่างฮัม มันพูดถึงที่ที่คุณอยู่ สภาพอากาศ เวลา สิ่งที่อยู่ใกล้ สิ่งที่คุณทำ และสิ่งที่คุณผ่านมา: มังกรตัวแรก ความตายครั้งแรก ที่เก่าๆ คำพูดแสดงเหนือหัวมันและในแชทในชื่อของคุณ ในโหมดเต็ม ผู้เล่นใกล้ๆ ก็ได้ยิน การตั้งค่า: เพื่อนพูด เต็ม ลดลง นานๆ ครั้ง หรือปิด", "Dostunun bir sesi var. Ara sıra ailesinin kendi tarzında dünya hakkında yorum yapar: bir İskelet kurudur (bir mezarda \"Sonunda. İleriyi düşünen biri.\"), bir Dev dobra (\"Büyük.\"), bir Süzülen tepenin ötesini merak eder, bir Boşluk Dostu bir şeylerin uğuldadığını duyar. Nerede olduğundan, havadan, saatten, yakındakilerden, ne yaptığından ve yaşadıklarından söz eder: ilk ejderhalar, ilk ölümler, eski uğrak yerler. Söz başının üstünde ve sohbette senin adınla görünür; Tam'da yakındaki oyuncular da duyar. Ayarlar: Dost konuşması, Tam, Azaltılmış, Nadir ya da Kapalı.", "Tu Amigo tiene voz. De vez en cuando comenta el mundo a la manera de su familia: un Esqueleto es seco («Por fin. Alguien que lo planeó con tiempo.» ante una tumba), un Coloso tajante («Grande.»), un Flotante quiere saber qué hay tras la colina, un Amigo Hueco oye zumbar cosas. Habla de dónde estás, del tiempo, de la hora, de lo que hay cerca, de lo que haces y de lo que has vivido: los primeros dragones, las primeras muertes, los viejos rincones. La frase aparece sobre su cabeza y en el chat con tu nombre; en Completo, la oyen los jugadores cercanos. Ajustes: Habla del Amigo, Completo, Reducido, Raro o Desactivado.", "Seu Amigo tem voz. De vez em quando ele comenta o mundo do jeito da família dele: um Esqueleto é seco (\"Finalmente. Alguém que se planejou.\" num túmulo), um Colosso é direto (\"Grande.\"), um Flutuante quer saber o que tem depois do morro, um Amigo Oco ouve coisas zumbindo. Ele fala de onde você está, do tempo, da hora, do que está perto, do que você está fazendo e do que você viveu: primeiros dragões, primeiras mortes, lugares antigos. A fala aparece sobre a cabeça dele e no chat com seu nome; no Completo, jogadores por perto ouvem. Configurações: Fala do Amigo, Completa, Reduzida, Rara ou Desligada.", "У вашего Друга появился голос. Время от времени он комментирует мир в манере своей семьи: Скелет сух («Наконец-то. Кто-то подумал заранее.» у могилы), Колосс прямолинеен («Большое.»), Парящий хочет знать, что за холмом, Друг из Пустоты слышит, как что-то гудит. Он говорит о том, где вы, о погоде, о времени суток, о том, что рядом, что вы делаете и что вы пережили: первые драконы, первые смерти, старые места. Фраза видна над его головой и в чате под вашим именем; в режиме «Полностью» её слышат игроки рядом. Настройки: речь Друга — Полностью, Реже, Редко или Выключено.", "У вашого Друга з'явився голос. Час від часу він коментує світ у манері своєї родини: Скелет сухий («Нарешті. Хтось подумав наперед.» біля могили), Колос прямолінійний («Велике.»), Ширяючий хоче знати, що за пагорбом, Друг із Порожнечі чує, як щось гуде. Він говорить про те, де ви, про погоду, пору доби, про те, що поруч, що ви робите і що ви пережили: перші дракони, перші смерті, старі місця. Фразу видно над його головою й у чаті під вашим ім'ям; у режимі «Повністю» її чують гравці поруч. Налаштування: мовлення Друга — Повністю, Менше, Рідко або Вимкнено."],
  "Rumours: ask townsfolk, traders and innkeepers what they've heard. Every settlement has its own, some true, some half-true, some nonsense, a few pointing at things nobody explains (a door under the lake, a village beyond the mountains that doesn't like Friends, King Hollis never leaving the castle). A new rumour is worth a little Presence. The game never says which are true.": ["噂：町の人々、商人、宿の主人に何を聞いたか尋ねてみましょう。どの集落にも独自の噂があり、本当のもの、半分本当のもの、でたらめなもの、そして誰も説明しないことを指すものもいくつか（湖の下の扉、フレンドを嫌う山の向こうの村、城から出ないホリス王）。新しい噂を聞くと少し名声が上がります。どれが本当かはゲームは決して教えません。", "소문: 마을 사람, 상인, 여관 주인에게 무슨 얘길 들었는지 물어보세요. 정착지마다 고유한 소문이 있어, 어떤 건 사실, 어떤 건 반쯤 사실, 어떤 건 헛소리이고, 몇몇은 아무도 설명하지 않는 것을 가리킵니다(호수 아래의 문, 프렌드를 싫어하는 산 너머 마을, 성을 떠나지 않는 홀리스 왕). 새 소문은 명성을 조금 줍니다. 무엇이 사실인지는 게임이 절대 말해 주지 않습니다.", "传闻：问问镇民、商人和旅店老板听说了什么。每个聚落都有自己的传闻，有的是真的，有的半真半假，有的是胡话，还有少数指向没人解释得了的事（湖底的门、山那边不喜欢伙伴的村子、从不离开城堡的霍利斯国王）。听到新传闻能获得少量声望。游戏永远不会告诉你哪些是真的。", "傳聞：問問鎮民、商人和旅店老闆聽說了什麼。每個聚落都有自己的傳聞，有的是真的，有的半真半假，有的是胡話，還有少數指向沒人解釋得了的事（湖底的門、山那邊不喜歡夥伴的村子、從不離開城堡的霍利斯國王）。聽到新傳聞能獲得少量聲望。遊戲永遠不會告訴你哪些是真的。", "Tin đồn: hỏi dân thị trấn, thương nhân và chủ quán trọ xem họ nghe được gì. Mỗi khu định cư có tin đồn riêng, có cái thật, có cái nửa thật, có cái vô lý, vài cái chỉ tới những điều không ai giải thích (một cánh cửa dưới hồ, một ngôi làng bên kia núi không thích Bạn, Vua Hollis không bao giờ rời lâu đài). Một tin đồn mới đáng chút Danh tiếng. Game không bao giờ nói cái nào là thật.", "Kabar burung: tanyakan warga kota, pedagang, dan pemilik penginapan apa yang mereka dengar. Setiap permukiman punya kabarnya sendiri, sebagian benar, sebagian setengah benar, sebagian omong kosong, beberapa menunjuk hal yang tak dijelaskan siapa pun (pintu di bawah danau, desa di balik pegunungan yang tak suka Sahabat, Raja Hollis yang tak pernah meninggalkan kastel). Kabar baru bernilai sedikit Kehadiran. Game tak pernah bilang mana yang benar.", "ข่าวลือ: ถามชาวเมือง พ่อค้า และเจ้าของโรงเตี๊ยมว่าได้ยินอะไรมา ทุกชุมชนมีข่าวลือของตัวเอง บางเรื่องจริง บางเรื่องจริงครึ่งเดียว บางเรื่องไร้สาระ และบางเรื่องชี้ไปที่สิ่งที่ไม่มีใครอธิบาย (ประตูใต้ทะเลสาบ หมู่บ้านเลยภูเขาที่ไม่ชอบเพื่อน กษัตริย์ฮอลลิสที่ไม่เคยออกจากปราสาท) ข่าวลือใหม่มีค่าชื่อเสียงเล็กน้อย เกมไม่เคยบอกว่าเรื่องไหนจริง", "Söylentiler: kasaba halkına, tüccarlara ve hancılara ne duyduklarını sor. Her yerleşimin kendi söylentileri var; bazıları doğru, bazıları yarı doğru, bazıları saçma, birkaçı kimsenin açıklamadığı şeyleri işaret ediyor (gölün altında bir kapı, dağların ötesinde Dostları sevmeyen bir köy, kaleden hiç çıkmayan Kral Hollis). Yeni bir söylenti biraz Şöhret değerinde. Oyun hangilerinin doğru olduğunu asla söylemez.", "Rumores: pregunta a la gente del pueblo, a los comerciantes y a los posaderos qué han oído. Cada asentamiento tiene los suyos, unos ciertos, otros medio ciertos, otros tonterías, y unos pocos apuntan a cosas que nadie explica (una puerta bajo el lago, un pueblo tras las montañas al que no le gustan los Amigos, el rey Hollis sin salir nunca del castillo). Un rumor nuevo vale un poco de Presencia. El juego nunca dice cuáles son ciertos.", "Boatos: pergunte ao povo da cidade, aos comerciantes e aos estalajadeiros o que eles ouviram. Cada povoado tem os seus, alguns verdadeiros, alguns meio verdadeiros, alguns bobagem, e uns poucos apontando para coisas que ninguém explica (uma porta sob o lago, uma vila além das montanhas que não gosta de Amigos, o rei Hollis que nunca sai do castelo). Um boato novo vale um pouco de Presença. O jogo nunca diz quais são verdade.", "Слухи: спрашивайте горожан, торговцев и трактирщиков, что они слышали. В каждом поселении свои слухи — правдивые, полуправдивые, чепуха, а несколько указывают на то, чего никто не объясняет (дверь под озером, деревня за горами, где не любят Друзей, король Холлис, который никогда не покидает замок). Новый слух приносит немного Славы. Игра никогда не говорит, какие из них правда.", "Чутки: питайте городян, торговців і корчмарів, що вони чули. У кожному поселенні свої чутки — правдиві, напівправдиві, нісенітниці, а кілька вказують на те, чого ніхто не пояснює (двері під озером, село за горами, де не люблять Друзів, король Голліс, який ніколи не покидає замку). Нова чутка приносить трохи Слави. Гра ніколи не каже, які з них правда."],
  "People notice you. Some NPCs greet your Friend's family the first time they meet it (a Skeleton at Dawnhold gets a look; a Colossus in Cragmaw, \"By the old stones\"). As your Presence grows they recognise you: \"Back already?\" at 20, your name at 40, \"Everyone here knows\" you at 70.": ["人々があなたに気づくように。一部のNPCは初めて会ったとき、フレンドのファミリーに反応します（ドーンホールドのスケルトンはじろりと見られ、クラグモーのコロッサスは「古き石にかけて」）。名声が上がると覚えられ、20で「もう戻ったのか？」、40で名前を呼ばれ、70で「ここじゃ誰もが知ってる」と言われます。", "사람들이 당신을 알아봅니다. 일부 NPC는 처음 만날 때 프렌드의 가문을 보고 인사합니다(돈홀드의 스켈레톤은 눈총을 받고, 크래그모의 콜로서스는 \"옛 돌에 걸고\"). 명성이 오르면 당신을 알아봅니다: 20에선 \"벌써 돌아왔어?\", 40에선 이름을, 70에선 \"여기선 다들 알지\".", "人们会注意到你。有些 NPC 第一次见到你的伙伴时会对它的家族打招呼（晨堡里的骷髅会挨几个白眼；崖口的巨像会听到「以古石之名」）。随着声望增长，他们会认出你：20 级时说「这么快就回来了？」，40 级时叫出你的名字，70 级时说「这里人人都认识」你。", "人們會注意到你。有些 NPC 第一次見到你的夥伴時會對牠的家族打招呼（晨堡裡的骷髏會挨幾個白眼；崖口的巨像會聽到「以古石之名」）。隨著聲望增長，他們會認出你：20 級時說「這麼快就回來了？」，40 級時叫出你的名字，70 級時說「這裡人人都認識」你。", "Mọi người để ý đến bạn. Một số NPC chào gia tộc Bạn của bạn lần đầu gặp (Skeleton ở Dawnhold bị nhìn chằm chằm; Colossus ở Cragmaw được nghe \"Nhân danh những hòn đá xưa\"). Khi Danh tiếng tăng, họ nhận ra bạn: \"Về rồi à?\" ở 20, gọi tên bạn ở 40, \"Ở đây ai cũng biết\" bạn ở 70.", "Orang-orang memperhatikanmu. Beberapa NPC menyapa keluarga Sahabatmu saat pertama bertemu (Skeleton di Dawnhold dipandangi; Colossus di Cragmaw disambut \"Demi batu-batu tua\"). Seiring Kehadiranmu tumbuh, mereka mengenalimu: \"Sudah kembali?\" di 20, namamu di 40, \"Semua orang di sini kenal\" kamu di 70.", "ผู้คนสังเกตคุณ NPC บางคนทักตระกูลเพื่อนของคุณเมื่อเจอครั้งแรก (Skeleton ที่ดอว์นโฮลด์ถูกมองแรง Colossus ในแครกมอว์ได้ยิน \"ด้วยนามแห่งศิลาโบราณ\") เมื่อชื่อเสียงเพิ่มพวกเขาจะจำคุณได้: \"กลับมาแล้วเหรอ\" ที่ 20 เรียกชื่อคุณที่ 40 และ \"ที่นี่ทุกคนรู้จัก\" คุณที่ 70", "İnsanlar seni fark ediyor. Bazı NPC'ler ilk karşılaştıklarında Dostunun ailesini selamlıyor (Dawnhold'da bir İskelet bakış yiyor; Cragmaw'da bir Dev \"Eski taşlar adına\" duyuyor). Şöhretin büyüdükçe seni tanıyorlar: 20'de \"Döndün mü bile?\", 40'ta adınla, 70'te \"Burada herkes tanır\" seni.", "La gente se fija en ti. Algunos PNJ saludan a la familia de tu Amigo la primera vez que la ven (un Esqueleto en Dawnhold se lleva una mirada; un Coloso en Cragmaw, «Por las piedras antiguas»). Según crece tu Presencia te reconocen: «¿Ya de vuelta?» a 20, tu nombre a 40, «Aquí todo el mundo te conoce» a 70.", "As pessoas reparam em você. Alguns NPCs cumprimentam a família do seu Amigo na primeira vez que a veem (um Esqueleto em Dawnhold leva uma olhada; um Colosso em Cragmaw ouve \"Pelas pedras antigas\"). Conforme sua Presença cresce, eles reconhecem você: \"Já de volta?\" no 20, seu nome no 40, \"Todo mundo aqui conhece\" você no 70.", "Вас замечают. Некоторые NPC при первой встрече реагируют на семью вашего Друга (на Скелета в Даунхолде косо смотрят; Колосса в Крэгмо встречают словами «Клянусь древними камнями»). С ростом Славы вас узнают: «Уже вернулся?» на 20, по имени на 40, «Тебя здесь все знают» на 70.", "Вас помічають. Деякі NPC під час першої зустрічі реагують на родину вашого Друга (на Скелета в Даунголді косо дивляться; Колоса в Крегмо зустрічають словами «Присягаюся давнім камінням»). Із ростом Слави вас упізнають: «Уже повернувся?» на 20, на ім'я на 40, «Тебе тут усі знають» на 70."],
  "Things that tell a story without saying it: a burned farmhouse in Westmarch with three beds and a child's wooden horse, footprints to the trees and nothing after; an altar used as a fence post in the Thistle Vale; ancient stonework under the Thistle road; a shrine deep in the Deadwood to a bearded figure whose face has been chiselled off, with a candle somebody keeps lit; a seized mechanism the size of a mill under Ironreach; a fisherman's shack on Southshore nobody has lived in for years; and watch-stones along the Westmarch road, every one toppled westward, from when Friendhollow's castle was built against something that came from the west.": ["語らずに物語を伝えるもの：Westmarch の焼けた農家（ベッドが3つと子どもの木馬、木々へ続く足跡、そしてその先には何もない）、アザミの谷で柵の杭にされた祭壇、アザミの道の下の古代の石組み、Deadwood の奥にある、顔を削り取られた髭の人物の祠（誰かが灯し続けるろうそくつき）、アイアンリーチの下にある風車ほどの大きさの固まった機械、何年も誰も住んでいないサウスショアの漁師小屋、そして Westmarch の道沿いの見張り石。どれも西へ倒れていて、フレンドホロウの城が西から来た何かに備えて建てられた頃のものです。", "말하지 않고 이야기를 전하는 것들: 침대 셋과 아이의 목마가 있는 Westmarch의 불탄 농가(나무까지 이어진 발자국, 그 뒤엔 아무것도 없음), 엉겅퀴 골짜기에서 울타리 말뚝으로 쓰이는 제단, 엉겅퀴 길 아래의 고대 석조물, Deadwood 깊은 곳에 얼굴이 깎여 나간 수염 난 인물의 사당(누군가 계속 켜 두는 촛불), 아이언리치 아래 풍차만 한 멈춘 기계, 몇 년째 아무도 살지 않는 사우스쇼어의 어부 오두막, 그리고 Westmarch 길을 따라 선 감시석들, 모두 서쪽으로 쓰러져 있습니다. 프렌드할로우 성이 서쪽에서 온 무언가에 맞서 지어졌을 때의 것이죠.", "不言自明的故事：Westmarch 一座烧毁的农舍，有三张床和一匹孩子的木马，脚印通向树林，之后什么也没有；蓟谷里被当作篱笆桩的祭坛；蓟谷路下的古老石作；Deadwood 深处一座神龛，供奉着一位脸被凿掉的大胡子人物，有人一直点着一支蜡烛；铁境地下一台磨坊大小的卡死机械；南岸一间多年无人居住的渔夫小屋；还有 Westmarch 路边的瞭望石，每一块都朝西倒下，来自友谷城堡为抵御某种从西方来的东西而建成的年代。", "不言自明的故事：Westmarch 一座燒毀的農舍，有三張床和一匹孩子的木馬，腳印通向樹林，之後什麼也沒有；薊谷裡被當作籬笆樁的祭壇；薊谷路下的古老石作；Deadwood 深處一座神龕，供奉著一位臉被鑿掉的大鬍子人物，有人一直點著一支蠟燭；鐵境地下一台磨坊大小的卡死機械；南岸一間多年無人居住的漁夫小屋；還有 Westmarch 路邊的瞭望石，每一塊都朝西倒下，來自友谷城堡為抵禦某種從西方來的東西而建成的年代。", "Những thứ kể chuyện mà không cần nói: một trang trại cháy ở Westmarch với ba chiếc giường và con ngựa gỗ của một đứa trẻ, dấu chân dẫn tới hàng cây rồi không còn gì nữa; một bàn thờ bị dùng làm cọc rào ở Thung lũng Kế; công trình đá cổ dưới con đường Thistle; một miếu thờ sâu trong Deadwood dành cho một nhân vật có râu bị đục mất mặt, với ngọn nến ai đó vẫn giữ cháy; một cỗ máy kẹt cứng to bằng cái cối xay dưới Ironreach; túp lều của một ngư dân ở Southshore không ai ở suốt nhiều năm; và những tảng đá canh dọc đường Westmarch, tảng nào cũng đổ về phía tây, từ thời lâu đài Friendhollow được xây để chống lại thứ gì đó đến từ phía tây.", "Hal-hal yang bercerita tanpa berkata: rumah pertanian terbakar di Westmarch dengan tiga ranjang dan kuda kayu seorang anak, jejak kaki menuju pepohonan lalu tak ada apa-apa; altar yang dipakai jadi tiang pagar di Lembah Thistle; batu kuno di bawah jalan Thistle; kuil jauh di dalam Deadwood untuk sosok berjanggut yang wajahnya dipahat habis, dengan lilin yang terus dinyalakan seseorang; mekanisme macet sebesar kincir di bawah Ironreach; gubuk nelayan di Southshore yang bertahun-tahun tak dihuni; dan batu jaga di sepanjang jalan Westmarch, semuanya roboh ke barat, sejak kastel Friendhollow dibangun untuk menghadapi sesuatu yang datang dari barat.", "สิ่งที่เล่าเรื่องโดยไม่ต้องพูด: บ้านไร่ที่ถูกเผาใน Westmarch มีเตียงสามหลังกับม้าไม้ของเด็ก รอยเท้าไปถึงแนวต้นไม้แล้วไม่มีอะไรต่อ แท่นบูชาที่ถูกใช้เป็นเสารั้วในหุบเขาทิสเซิล งานหินโบราณใต้ถนนทิสเซิล ศาลเจ้าลึกใน Deadwood ของบุคคลมีเคราที่ใบหน้าถูกสกัดออก มีเทียนที่ใครสักคนจุดไว้ตลอด กลไกที่ติดตายขนาดเท่าโรงโม่ใต้ไอรอนรีช กระท่อมชาวประมงที่เซาท์ชอร์ที่ไม่มีใครอยู่มาหลายปี และหินยามตามถนน Westmarch ทุกก้อนล้มไปทางตะวันตก ตั้งแต่สมัยที่ปราสาทเฟรนด์ฮอลโลว์ถูกสร้างเพื่อต้านบางสิ่งที่มาจากทางตะวันตก", "Söylemeden bir hikâye anlatan şeyler: Westmarch'ta üç yataklı ve bir çocuğun tahta atıyla yanmış bir çiftlik evi, ağaçlara giden ayak izleri ve sonrasında hiçbir şey; Devedikeni Vadisi'nde çit kazığı olarak kullanılan bir sunak; Devedikeni yolunun altında eski taş işçiliği; Deadwood'un derinliklerinde yüzü kazınmış sakallı bir figüre adanmış, birinin hep yaktığı bir mumu olan bir tapınak; Ironreach'in altında değirmen büyüklüğünde sıkışmış bir mekanizma; Southshore'da yıllardır kimsenin yaşamadığı bir balıkçı kulübesi; ve Westmarch yolu boyunca, her biri batıya devrilmiş gözcü taşları, Friendhollow kalesinin batıdan gelen bir şeye karşı inşa edildiği zamanlardan.", "Cosas que cuentan una historia sin decirla: una granja quemada en Westmarch con tres camas y un caballito de madera, huellas hacia los árboles y nada después; un altar usado como poste de cerca en El Valle del Cardo; cantería antigua bajo el camino del Cardo; un santuario en lo hondo del Deadwood a una figura barbuda a la que le han cincelado la cara, con una vela que alguien mantiene encendida; un mecanismo atascado del tamaño de un molino bajo Ironreach; la choza de un pescador en Southshore donde nadie vive desde hace años; y piedras de vigía a lo largo del camino de Westmarch, todas derribadas hacia el oeste, de cuando se construyó el castillo de Friendhollow contra algo que vino del oeste.", "Coisas que contam uma história sem dizer: uma fazenda queimada em Westmarch com três camas e um cavalinho de madeira de criança, pegadas até as árvores e nada depois; um altar usado como mourão no Vale do Cardo; cantaria antiga sob a estrada do Cardo; um santuário no fundo do Deadwood a uma figura barbuda cujo rosto foi cinzelado, com uma vela que alguém mantém acesa; um mecanismo emperrado do tamanho de um moinho sob Ironreach; o barraco de um pescador em Southshore onde ninguém mora há anos; e pedras de vigia ao longo da estrada de Westmarch, todas tombadas para o oeste, da época em que o castelo de Friendhollow foi erguido contra algo que veio do oeste.", "Вещи, которые рассказывают историю без слов: сгоревший фермерский дом в Westmarch с тремя кроватями и детской деревянной лошадкой, следы к деревьям и больше ничего; алтарь, ставший столбом забора в Чертополоховой долине; древняя каменная кладка под Чертополоховой дорогой; святилище глубоко в Deadwood бородатой фигуре со стёсанным лицом и свечой, которую кто-то не даёт погаснуть; заклинивший механизм размером с мельницу под Айронричем; рыбацкая хижина в Саутшоре, где никто не живёт много лет; и сторожевые камни вдоль дороги Westmarch, все до одного повалены на запад, — со времён, когда замок Френдхоллоу строили против чего-то, пришедшего с запада.", "Речі, що розповідають історію без слів: згорілий фермерський дім у Westmarch із трьома ліжками й дитячим дерев'яним коником, сліди до дерев і більше нічого; вівтар, що став стовпом паркану в Будяковій долині; давня кам'яна кладка під Будяковою дорогою; святиня глибоко в Deadwood бородатій постаті зі стесаним обличчям і свічкою, яку хтось не дає згаснути; заклинений механізм завбільшки з млин під Айронрічем; рибальська хатина в Саутшорі, де ніхто не живе багато років; і сторожові камені вздовж дороги Westmarch, усі до одного повалені на захід, — з часів, коли замок Френдголлоу будували проти чогось, що прийшло із заходу."],
  "Fernwick has a history: Rowan will tell you how its children learn their trees before their letters, and Hazel, once her quest is done, about the first war bow and the one in the castle armoury that has never been drawn.": ["ファーンウィックには歴史があります：Rowan は村の子どもたちが文字より先に木の名前を覚えることを話してくれ、ヘイゼルはクエストのあと、最初のウォーボウと、城の武器庫にある一度も引かれたことのない弓のことを話してくれます。", "펀윅엔 역사가 있습니다: Rowan은 이곳 아이들이 글자보다 나무를 먼저 배운다고 들려주고, 헤이즐은 퀘스트를 마치면 첫 전쟁활과 성 무기고에 있는 한 번도 당겨진 적 없는 활 이야기를 해 줍니다.", "蕨村有它的历史：Rowan 会告诉你这里的孩子先认树再识字，黑兹尔在她的任务完成后会讲起第一张战弓，以及城堡军械库里那张从未被拉开过的弓。", "蕨村有它的歷史：Rowan 會告訴你這裡的孩子先認樹再識字，黑茲爾在她的任務完成後會講起第一張戰弓，以及城堡軍械庫裡那張從未被拉開過的弓。", "Fernwick có lịch sử: Rowan sẽ kể cho bạn rằng trẻ con ở đây học tên cây trước khi học chữ, và Hazel, sau khi xong nhiệm vụ của cô, kể về cây cung chiến đầu tiên và cây cung trong kho vũ khí lâu đài chưa từng được kéo.", "Fernwick punya sejarah: Rowan akan bercerita bagaimana anak-anaknya belajar nama pohon sebelum huruf, dan Hazel, setelah misinya selesai, tentang busur perang pertama dan busur di gudang senjata kastel yang tak pernah ditarik.", "เฟิร์นวิกมีประวัติศาสตร์: Rowan จะเล่าว่าเด็กๆ ที่นี่เรียนรู้จักต้นไม้ก่อนตัวอักษร และเฮเซล เมื่อเควสต์ของเธอเสร็จ จะเล่าเรื่องธนูศึกคันแรกและคันที่อยู่ในคลังอาวุธปราสาทที่ไม่เคยถูกง้าง", "Fernwick'in bir tarihi var: Rowan sana çocuklarının harflerden önce ağaçlarını nasıl öğrendiğini anlatır, Hazel de görevi bitince ilk savaş yayını ve kale cephaneliğinde hiç gerilmemiş olanı anlatır.", "Fernwick tiene su historia: Rowan te contará que sus niños aprenden los árboles antes que las letras, y Hazel, cuando termines su misión, te hablará del primer arco de guerra y del que hay en la armería del castillo que nunca se ha tensado.", "Fernwick tem uma história: Rowan conta como as crianças de lá aprendem as árvores antes das letras, e Hazel, depois da missão dela, fala do primeiro arco de guerra e do que está no arsenal do castelo e nunca foi puxado.", "У Фернвика есть история: Rowan расскажет, как его дети узнают деревья раньше букв, а Хейзел после своего квеста — о первом боевом луке и о том, что хранится в замковой оружейной и ни разу не был натянут.", "У Фернвіка є історія: Rowan розповість, як тутешні діти пізнають дерева раніше за літери, а Гейзел після свого квесту — про перший бойовий лук і про той, що зберігається в замковій зброярні й жодного разу не був натягнутий."],
  "Every weapon and piece of armour in the six ore metals can now be bought somewhere: the Ironreach Armoury in Cragmaw (Brenna Anvilsong) sells every glimmer and rarite piece, helms to greaves, daggers to war hammers; Gravesend's Last Lantern sells moonsilver plate salvaged from the Deadwood. Worth the walk.": ["6つの鉱石金属の武器と防具はすべて、どこかで買えるようになりました：クラグモーのアイアンリーチ武具店（ブレナ・アンヴィルソング）はグリマーとレアライトの全品を、兜からすね当て、短剣からウォーハンマーまで販売。グレイヴセンドの Last Lantern は Deadwood から回収したムーンシルバーの鎧を売っています。歩いて行く価値あり。", "광석 금속 여섯 가지의 모든 무기와 갑옷을 이제 어딘가에서 살 수 있습니다: 크래그모의 아이언리치 무기고(브레나 앤빌송)는 글리머와 레어라이트 장비를 투구부터 정강이받이, 단검부터 전쟁망치까지 모두 팔고, 그레이브센드의 Last Lantern은 Deadwood에서 건진 월은 판금 갑옷을 팝니다. 걸어갈 가치가 있습니다.", "六种矿石金属的所有武器和护甲现在都能在某处买到：崖口的铁境军械铺（布伦娜·砧歌）出售所有微光和稀晶装备，从头盔到护胫、从匕首到战锤；墓终的 Last Lantern 出售从 Deadwood 打捞来的月银板甲。值得走一趟。", "六種礦石金屬的所有武器和護甲現在都能在某處買到：崖口的鐵境軍械舖（布倫娜·砧歌）出售所有微光和稀晶裝備，從頭盔到護脛、從匕首到戰錘；墓終的 Last Lantern 出售從 Deadwood 打撈來的月銀板甲。值得走一趟。", "Mọi vũ khí và giáp bằng sáu kim loại quặng giờ đều mua được ở đâu đó: Kho vũ khí Ironreach ở Cragmaw (Brenna Anvilsong) bán mọi món ánh kim và rarit, từ mũ giáp đến giáp chân, từ dao găm đến búa chiến; Last Lantern ở Gravesend bán giáp bạc trăng nhặt được từ Deadwood. Đáng để đi bộ.", "Setiap senjata dan zirah dari enam logam bijih kini bisa dibeli di suatu tempat: Gudang Senjata Ironreach di Cragmaw (Brenna Anvilsong) menjual semua barang kemilau dan rarit, dari helm hingga pelindung kaki, belati hingga palu perang; Last Lantern di Gravesend menjual zirah pelat perak bulan yang diselamatkan dari Deadwood. Layak ditempuh.", "อาวุธและเกราะทุกชิ้นของโลหะแร่หกชนิดตอนนี้ซื้อได้ที่ไหนสักแห่ง: คลังอาวุธไอรอนรีชในแครกมอว์ (เบรนนา แอนวิลซอง) ขายของประกายแสงและแรไรต์ทุกชิ้น ตั้งแต่หมวกเกราะถึงสนับแข้ง กริชถึงค้อนศึก Last Lantern ของเกรฟเซนด์ขายเกราะแผ่นเงินจันทร์ที่กู้มาจาก Deadwood คุ้มค่าที่จะเดินไป", "Altı cevher metalinden her silah ve zırh parçası artık bir yerden alınabiliyor: Cragmaw'daki Ironreach Cephaneliği (Brenna Anvilsong) miğferden dizliğe, hançerden savaş çekicine her parıltı ve rarit parçayı satıyor; Gravesend'in Last Lantern'ı Deadwood'dan kurtarılmış ay gümüşü zırh satıyor. Yürümeye değer.", "Todas las armas y piezas de armadura de los seis metales de mineral se pueden comprar ya en algún sitio: la Armería de Ironreach en Cragmaw (Brenna Cantoyunque) vende todas las piezas de destello y rarita, de yelmos a grebas y de dagas a martillos de guerra; el Last Lantern de Gravesend vende armadura de plata lunar rescatada del Deadwood. Merece el paseo.", "Toda arma e peça de armadura dos seis metais de minério agora pode ser comprada em algum lugar: o Arsenal de Ironreach em Cragmaw (Brenna Canto-de-Bigorna) vende todas as peças de lampejo e rarita, de elmos a grevas, de adagas a martelos de guerra; o Last Lantern de Gravesend vende armadura de prata lunar resgatada do Deadwood. Vale a caminhada.", "Любое оружие и доспехи из шести рудных металлов теперь где-то продаются: Оружейная Айронрича в Крэгмо (Бренна Песнь Наковальни) продаёт все вещи из мерцалита и рарита — от шлемов до поножей, от кинжалов до боевых молотов; Last Lantern в Грейвсенде продаёт латы из лунного серебра, вынесенные из Deadwood. Стоит прогуляться.", "Будь-яку зброю й обладунки з шести рудних металів тепер десь продають: Зброярня Айронріча в Крегмо (Бренна Пісня Ковадла) продає всі речі з мерехтиту й рариту — від шоломів до наголінників, від кинджалів до бойових молотів; Last Lantern у Грейвсенді продає лати з місячного срібла, винесені з Deadwood. Варто прогулятися."],
  "The website has a Lore page: the Realm's history, the Old Friend, the First Friends, the Hollow, and a card for every region (who lives there, what they believe, fear, trade and whisper). Deliberately incomplete.": ["ウェブサイトに伝承ページができました：レルムの歴史、古き友、First Friends、虚ろなるもの、そして地域ごとのカード（誰が住み、何を信じ、何を恐れ、何を商い、何をささやくか）。あえて不完全にしています。", "웹사이트에 설화 페이지가 생겼습니다: 렐름의 역사, 옛 친구, First Friends, 공허, 그리고 지역마다 카드(누가 살고, 무엇을 믿고, 두려워하고, 거래하고, 속삭이는지). 일부러 다 채우지 않았습니다.", "网站上有了传说页面：王国的历史、故友、First Friends、虚空，以及每个地区的卡片（谁住在那里，他们相信什么、害怕什么、交易什么、私下传些什么）。刻意留白。", "網站上有了傳說頁面：王國的歷史、故友、First Friends、虛空，以及每個地區的卡片（誰住在那裡，他們相信什麼、害怕什麼、交易什麼、私下傳些什麼）。刻意留白。", "Trang web có trang Truyền thuyết: lịch sử Vương quốc, Người Bạn Cũ, First Friends, Hư không, và một thẻ cho mỗi vùng (ai sống ở đó, họ tin gì, sợ gì, buôn bán gì và thì thầm gì). Cố ý để dang dở.", "Situs web punya halaman Kisah: sejarah Realm, Sahabat Lama, First Friends, Hampa, dan kartu untuk setiap wilayah (siapa yang tinggal di sana, apa yang mereka percayai, takuti, perdagangkan, dan bisikkan). Sengaja tak lengkap.", "เว็บไซต์มีหน้าตำนาน: ประวัติศาสตร์ของอาณาจักร สหายเก่า First Friends ความว่างเปล่า และการ์ดของทุกภูมิภาค (ใครอาศัยอยู่ เชื่ออะไร กลัวอะไร ค้าขายอะไร และกระซิบอะไร) ตั้งใจให้ไม่ครบ", "Web sitesinde bir Efsane sayfası var: Diyar'ın tarihi, Eski Dost, First Friends, Boşluk ve her bölge için bir kart (orada kim yaşıyor, neye inanıyor, neden korkuyor, ne ticareti yapıyor, ne fısıldıyor). Bilerek eksik.", "La web tiene una página de Historia: la historia del Reino, el Viejo Amigo, los First Friends, el Hueco y una ficha por región (quién vive allí, qué creen, qué temen, con qué comercian y qué susurran). Incompleta a propósito.", "O site tem uma página de Lore: a história do Reino, o Velho Amigo, os First Friends, o Oco e um cartão para cada região (quem vive lá, no que acreditam, o que temem, negociam e sussurram). Incompleta de propósito.", "На сайте появилась страница преданий: история Королевства, Старый Друг, First Friends, Пустота и карточка для каждого региона (кто там живёт, во что верят, чего боятся, чем торгуют и о чём шепчутся). Неполная — нарочно.", "На сайті з'явилася сторінка переказів: історія Королівства, Старий Друг, First Friends, Порожнеча й картка для кожного регіону (хто там живе, у що вірять, чого бояться, чим торгують і про що шепочуться). Неповна — навмисно."],
  "The spellbook has tabs: Combat, Curses, Utility and Teleports, each counting what you've learnt. Eleven new glides: to Fernwick, Highcairn, Dawnhold and every village of the wider world (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) and to Ember Tamsin's camp at Ashfall. All but Highcairn are learnt by doing the place's own quest; the sigils are the easy part.": ["呪文書にタブができました：戦闘、呪い、補助、テレポート。それぞれ習得数を数えます。新しい滑空が11種：ファーンウィック、ハイケアン、ドーンホールド、広い世界のすべての村（グレイヴセンド、ソルトマロウ、ホリホック、ダイムーア、トールグラス、クラグモー、クイルヘイヴン）、そしてアッシュフォールのエンバー・タムシンの野営地へ。ハイケアン以外は、その土地のクエストをこなすと覚えられます。シジルは簡単な部分です。", "주문서에 탭이 생겼습니다: 전투, 저주, 보조, 순간이동. 각각 배운 수를 셉니다. 새 활공 열하나: 펀윅, 하이케언, 돈홀드, 넓은 세상의 모든 마을(그레이브센드, 솔트매로, 할리혹, 다이무어, 톨그래스, 크래그모, 퀼헤이븐), 그리고 애시폴의 엠버 탐신 야영지로. 하이케언을 빼곤 모두 그곳의 퀘스트를 해야 배웁니다. 인장은 쉬운 부분이죠.", "法术书有了标签：战斗、诅咒、辅助和传送，各自计算你学会的数量。十一个新滑翔术：前往蕨村、高冢、晨堡以及更广阔世界的每个村庄（墓终、盐髓港、蜀葵村、染原、高草原、崖口、羽港），还有灰落的余烬塔姆欣营地。除了高冢，其余都要完成当地的任务才能学会；印记反倒是简单的部分。", "法術書有了分頁：戰鬥、詛咒、輔助和傳送，各自計算你學會的數量。十一個新滑翔術：前往蕨村、高塚、晨堡以及更廣闊世界的每個村莊（墓終、鹽髓港、蜀葵村、染原、高草原、崖口、羽港），還有灰落的餘燼塔姆欣營地。除了高塚，其餘都要完成當地的任務才能學會；印記反倒是簡單的部分。", "Sách phép có các thẻ: Chiến đấu, Lời nguyền, Tiện ích và Dịch chuyển, mỗi thẻ đếm những gì bạn đã học. Mười một phép lướt mới: đến Fernwick, Highcairn, Dawnhold và mọi ngôi làng của thế giới rộng lớn (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) và đến trại của Ember Tamsin ở Ashfall. Trừ Highcairn, tất cả đều học được bằng cách làm nhiệm vụ của chính nơi đó; ấn là phần dễ.", "Buku mantra punya tab: Tempur, Kutukan, Utilitas, dan Teleportasi, masing-masing menghitung yang sudah kau pelajari. Sebelas luncuran baru: ke Fernwick, Highcairn, Dawnhold, dan setiap desa di dunia yang lebih luas (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) dan ke perkemahan Ember Tamsin di Ashfall. Semua kecuali Highcairn dipelajari dengan menjalankan misi tempat itu sendiri; sigilnya bagian yang mudah.", "คัมภีร์เวทมีแท็บ: ต่อสู้ คำสาป อรรถประโยชน์ และเทเลพอร์ต แต่ละแท็บนับสิ่งที่คุณเรียนรู้แล้ว คาถาร่อนใหม่สิบเอ็ดบท: ไปเฟิร์นวิก ไฮแคร์น ดอว์นโฮลด์ และทุกหมู่บ้านของโลกที่กว้างขึ้น (เกรฟเซนด์ ซอลต์แมร์โรว์ ฮอลลีฮ็อก ไดมัวร์ ทอลกราส แครกมอว์ ควิลเฮเวน) และค่ายของเอมเบอร์ แทมซินที่แอชฟอลล์ ทุกบทยกเว้นไฮแคร์นต้องทำเควสต์ของที่นั้นถึงจะเรียนได้ ผนึกเป็นส่วนที่ง่าย", "Büyü kitabının sekmeleri var: Savaş, Lanetler, Yardımcı ve Işınlanma; her biri öğrendiklerini sayıyor. On bir yeni süzülme: Fernwick'e, Highcairn'e, Dawnhold'a ve daha geniş dünyanın her köyüne (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) ve Ashfall'daki Ember Tamsin'in kampına. Highcairn dışındakilerin hepsi o yerin kendi görevini yaparak öğreniliyor; mühürler işin kolay kısmı.", "El libro de hechizos tiene pestañas: Combate, Maldiciones, Utilidad y Teletransportes, cada una con lo que has aprendido. Once planeos nuevos: a Fernwick, Highcairn, Dawnhold y a cada pueblo del mundo más amplio (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) y al campamento de Ember Tamsin en Ashfall. Todos menos Highcairn se aprenden haciendo la misión del lugar; los sigilos son lo fácil.", "O livro de feitiços tem abas: Combate, Maldições, Utilidade e Teletransportes, cada uma contando o que você aprendeu. Onze planeios novos: para Fernwick, Highcairn, Dawnhold e cada vila do mundo maior (Gravesend, Saltmarrow, Hollyhock, Dyemoor, Tallgrass, Cragmaw, Quillhaven) e para o acampamento de Ember Tamsin em Ashfall. Todos, menos Highcairn, são aprendidos fazendo a missão do próprio lugar; os sigilos são a parte fácil.", "У книги заклинаний появились вкладки: Бой, Проклятия, Полезное и Телепорты, каждая со счётчиком выученного. Одиннадцать новых перелётов: во Фернвик, Хайкэрн, Даунхолд и во все деревни широкого мира (Грейвсенд, Солтмэрроу, Холлихок, Даймур, Толлграсс, Крэгмо, Квиллхейвен) и в лагерь Эмбер Тамсин в Эшфолле. Все, кроме Хайкэрна, изучаются через квест самого места; печати — это простая часть.", "У книги заклинань з'явилися вкладки: Бій, Прокляття, Корисне й Телепорти, кожна з лічильником вивченого. Одинадцять нових перельотів: до Фернвіка, Гайкерна, Даунголда й до всіх сіл широкого світу (Грейвсенд, Солтмерроу, Голлігок, Даймур, Толлграс, Крегмо, Квіллгейвен) і до табору Ембер Тамсін в Ешфоллі. Усі, крім Гайкерна, вивчаються через квест самого місця; печатки — це проста частина."],
};
